/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Helper class for all CCR related calculation
/// </summary>
public class METTMSCCRTableHelper
{
    SalesId             salesId;
    Set ccrToteIds;
    METTMSEngineSalesOrderProccessLinesTmp processLinesTmp;
    InventParameters    inventParameters;   

    Map                 commodityMap;
    // Sum variables for the SO
    METWHSPalletVolume  sumRepackContainersCaseVolume, sumRepackContainersToteVolume;
    int                 sumRepackContainersQty, sumRepackContainersQtyTOB, sumRepackContainersQtyNotTOB;
    METWHSPalletWeight  sumRepackContainersToteWeight;

    METWMSPicklistNumber wmsPicklistNumber;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_ccrToteIds">Set of already counted CCR Tote Ids</param>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_wmsPicklistNumber">AIS WMS picking list number</param>
void new(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp, Set _ccrToteIds, SalesId _salesId, METWMSPicklistNumber _wmsPicklistNumber)
{
    processLinesTmp     = _processLinesTmp;
    salesId             = _salesId;
    ccrToteIds          = _ccrToteIds;

    inventParameters = InventParameters::find();

    commodityMap = new Map(Types::String, Types::Container);

    wmsPicklistNumber = _wmsPicklistNumber;
}

/// <summary>
/// Constructs a new TMS engine CCR helper class.
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_ccrToteIds">Set of already counted CCR Tote Ids</param>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_wmsPicklistNumber">AIS WMS picking list number</param>
/// <returns>An instance of <c>METTMSCCRTableHelper</c></returns>
public static METTMSCCRTableHelper construct(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp, Set _ccrToteIds, SalesId _salesId, METWMSPicklistNumber _wmsPicklistNumber)
{
    return new METTMSCCRTableHelper(_processLinesTmp, _ccrToteIds, _salesId, _wmsPicklistNumber);
}

/// <summary>
/// Main calculation method
/// </summary>
/// <returns>Updated set of counted CCR Tote Ids</returns>
/// <remarks>
/// Executed per SO finalisation order/picking list number combination
/// </remarks>
Set calc()
{
    METCCRTable ccrTable;
    METWHSPalletVolume    whsCaseVolume;
    METWHSPalletVolume    whsToteVolume;
    METWHSPalletWeight    whsToteWeight;
    METTMSEngineSalesOrderProccessLinesTmp  processLinesTmpLocal;
    METTMSEngineSalesOrderProccessLinesTmp  lineTmpSum;
    boolean first = true;
    METCommodity prevCommodity;

    METWHSPalletVolume  sumRepackContainersByCommodityCaseVolume, sumRepackContainersByCommodityToteVolume;
    int                 sumRepackContainersByCommodityQty, sumRepackContainersByCommodityQtyTOB, sumRepackContainersByCommodityQtyNotTOB;
    METWHSPalletWeight  sumRepackContainersByCommodityToteWeight;

    processLinesTmpLocal.linkPhysicalTableInstance(processLinesTmp);
    lineTmpSum.linkPhysicalTableInstance(processLinesTmp);               

    // Get all the unique CCR Tote IDs by WH and line commodity
    while select ToteId
            from ccrTable
        group by ToteId, InventLocationId
           where ccrTable.SalesId        == salesId
              && ccrTable.PickingRouteId == wmsPicklistNumber // CCR has the WMS pick list number (from AIS)
              && ccrTable.ToteId         != ''
                join processLinesTmpLocal
            group by LineCommodity
               where processLinesTmpLocal.SalesId == ccrTable.SalesId
                  && processLinesTmpLocal.ItemId  == ccrTable.ItemId
    {
        // if the commodity changed, insert values in the map
        if (!first && prevCommodity != processLinesTmpLocal.LineCommodity)
        {
            commodityMap.insert(prevCommodity, [sumRepackContainersByCommodityQty,
                                                sumRepackContainersByCommodityQtyTOB,
                                                sumRepackContainersByCommodityQtyNotTOB,
                                                sumRepackContainersByCommodityCaseVolume,
                                                sumRepackContainersByCommodityToteVolume,
                                                sumRepackContainersByCommodityToteWeight]);
        }

        // if tote id not previously added in set for another SO
        if (!ccrToteIds.in(ccrTable.ToteId))
        {
            ccrToteIds.add(ccrTable.ToteId);

            [whsCaseVolume, whsToteVolume, whsToteWeight] = this.getContainerTypeParameters(ccrTable.InventLocationId);

            // increment qty (count)
            sumRepackContainersByCommodityQty++;

            // increment count TOB
            if (processLinesTmpLocal.LineCommodity == METConstants::tobCommodity)
            {
                sumRepackContainersByCommodityQtyTOB++;
            }
            else
            {
                // increment count <> TOB
                sumRepackContainersByCommodityQtyNotTOB++;
            }

            // sum volume
            sumRepackContainersByCommodityCaseVolume += whsCaseVolume;
            sumRepackContainersByCommodityToteVolume += whsToteVolume;

            // sum weight
            sumRepackContainersByCommodityToteWeight += whsToteWeight;                
        }

        if (first)
        {
            first = false;
        }

        prevCommodity = processLinesTmpLocal.LineCommodity;
    }

    // insert values in the map
    commodityMap.insert(prevCommodity, [sumRepackContainersByCommodityQty,
                                        sumRepackContainersByCommodityQtyTOB,
                                        sumRepackContainersByCommodityQtyNotTOB,
                                        sumRepackContainersByCommodityCaseVolume,
                                        sumRepackContainersByCommodityToteVolume,
                                        sumRepackContainersByCommodityToteWeight]);

    // Increment total sum for the SO
    sumRepackContainersQty += sumRepackContainersByCommodityQty;
    sumRepackContainersQtyTOB += sumRepackContainersByCommodityQtyTOB;
    sumRepackContainersQtyNotTOB += sumRepackContainersByCommodityQtyNotTOB;
    sumRepackContainersCaseVolume += sumRepackContainersByCommodityCaseVolume;
    sumRepackContainersToteVolume += sumRepackContainersByCommodityToteVolume;
    sumRepackContainersToteWeight += sumRepackContainersByCommodityToteWeight;

    return ccrToteIds;
}

/// <summary>
/// Get container type parameters for cardboard and plastic
/// </summary>
/// <param name = "_inventLocationId">Warehouse</param>
/// <returns>Container with case/tote volume and tote weight</returns>
protected container getContainerTypeParameters(InventLocationId _inventLocationId)
{
    METContainerTypeTable containerTypeTable;
    METWHSPalletVolume    whsCaseVolume;
    METWHSPalletVolume    whsToteVolume;
    METWHSPalletWeight    whsToteWeight;

    containerTypeTable   = METContainerTypeTable::find(inventParameters.METCardboardContainerID, _inventLocationId);
    whsCaseVolume   = containerTypeTable.ContainerVolume;

    containerTypeTable   = METContainerTypeTable::find(inventParameters.METPlasticContainerID, _inventLocationId);
    whsToteVolume   = containerTypeTable.ContainerVolume;
    whsToteWeight   = containerTypeTable.Weight;

    return [whsCaseVolume, whsToteVolume, whsToteWeight];
}

/// <summary>
/// Get CCR results by commodity
/// </summary>
/// <param name = "_commodity">Commodity</param>
/// <returns>Container of CCR results for specified commodity</returns>
public container getCommodityResults(METCommodity _commodity)
{
    container ret;
    MapEnumerator me = new MapEnumerator(commodityMap);

    while (me.moveNext())
    {
        if (me.currentKey() == _commodity)
        {
            return me.currentValue();
        }
    }

    return ret;
}

/// <summary>
/// Get total CCR results for the SO
/// </summary>
/// <returns>Container of total CCR results</returns>
public container getSumCommodityResults()
{
    return [sumRepackContainersQty,
            sumRepackContainersQtyTOB,
            sumRepackContainersQtyNotTOB,
            sumRepackContainersCaseVolume,
            sumRepackContainersToteVolume,
            sumRepackContainersToteWeight];
}
